/*
 * Helper function to test that a server attempting to read early data can
 * handle a connection from a client where the early data should be skipped.
 * testtype: 0 == No HRR
 * testtype: 1 == HRR
 * testtype: 2 == HRR, invalid early_data sent after HRR
 * testtype: 3 == recv_max_early_data set to 0
 */
static int early_data_skip_helper(int testdtls, int testtype, int cipher, int idx)
{
    SSL_CTX *cctx = NULL, *sctx = NULL;
    SSL *clientssl = NULL, *serverssl = NULL;
    int testresult = 0;
    SSL_SESSION *sess = NULL;
    unsigned char buf[20];
    size_t readbytes, written;
    const SSL_METHOD *smeth, *cmeth;
    int vermin, vermax = 0;

    if (testdtls) {
        smeth = DTLS_server_method();
        cmeth = DTLS_client_method();
        vermin = DTLS1_VERSION;
    } else {
        smeth = TLS_server_method();
        cmeth = TLS_client_method();
        vermin = TLS1_VERSION;
    }

    if (is_fips && cipher >= 4)
        return 1;

    /*
     * RFC 9147 (DTLS 1.3): TLS_AES_128_CCM_8_SHA256 MUST NOT be used in
     * DTLS without additional safeguards against forgery, which we do not
     * implement, so this cipher is not offered under DTLS.
     */
    if (testdtls && cipher == 0)
        return 1;

    if (ciphersuites[cipher] == NULL)
        return TEST_skip("Cipher not supported");

    if (!TEST_true(create_ssl_ctx_pair(libctx, smeth, cmeth, vermin, vermax,
            &sctx, &cctx, cert, privkey)))
        goto end;

    if (cipher == 0 || cipher == 5 || cipher == 6) {
        SSL_CTX_set_security_level(sctx, 0);
        SSL_CTX_set_security_level(cctx, 0);
    }

    if (!TEST_true(SSL_CTX_set_ciphersuites(sctx, ciphersuites[cipher])))
        goto end;
    if (idx == 2) {
        /*
         * The external PSK (see create_a_psk) is stamped with a fixed
         * ciphersuite that need not be the one under test.  For the client to
         * offer 0-RTT that ciphersuite must be among those it offers, so offer
         * it alongside the ciphersuite under test.  The server offers only the
         * ciphersuite under test, so the one it selects differs from the PSK's
         * whenever the two are not the same.
         */
        char clientsuites[128];

        snprintf(clientsuites, sizeof(clientsuites), "%s:%s",
            ciphersuites[cipher],
            (cipher == 2 || cipher == 6)
                ? "TLS_AES_256_GCM_SHA384"
                : "TLS_AES_128_GCM_SHA256");
        if (!TEST_true(SSL_CTX_set_ciphersuites(cctx, clientsuites)))
            goto end;
    } else if (!TEST_true(SSL_CTX_set_ciphersuites(cctx, ciphersuites[cipher]))) {
        goto end;
    }

    if (!TEST_true(setupearly_data_test(&cctx, &sctx, &clientssl,
            &serverssl, &sess, idx,
            (cipher == 2 || cipher == 6)
                ? SHA384_DIGEST_LENGTH
                : SHA256_DIGEST_LENGTH,
            testdtls)))
        goto end;

    if (testtype == 1 || testtype == 2) {
        /* Force an HRR to occur */
#if defined(OPENSSL_NO_EC)
        if (!TEST_true(SSL_set1_groups_list(serverssl, "ffdhe3072")))
            goto end;
#else
        if (!TEST_true(SSL_set1_groups_list(serverssl, "P-384")))
            goto end;
#endif
    } else if (idx == 2) {
        /*
         * We force early_data rejection by ensuring the PSK identity is
         * unrecognised
         */
        srvid = "Dummy Identity";
